SELECT COUNT(1)
FROM app_user_movie_action
WHERE movie_id = #{movieId}
  AND legacy_userid = #{legacyUserId}
  AND action_type = #{actionType}

mapper.delete:
DELETE FROM app_user_movie_action
WHERE movie_id = #{movieId}
  AND legacy_userid = #{legacyUserId}
  AND action_type = #{actionType}

mapper.update:
UPDATE app_movie m
SET
  m.favorite_count = (
    SELECT COUNT(1)
    FROM app_user_movie_action a
    WHERE a.movie_id = #{movieId}
      AND a.action_type = 'favorite'
  ),
  m.like_count = (
    SELECT COUNT(1)
    FROM app_user_movie_action a
    WHERE a.movie_id = #{movieId}
      AND a.action_type = 'like'
  ),
  m.dislike_count = (
    SELECT COUNT(1)
    FROM app_user_movie_action a
    WHERE a.movie_id = #{movieId}
      AND a.action_type = 'dislike'
  )
WHERE m.id = #{movieId}

mapper.select:
SELECT a.id AS actionId, m.id AS movieId, m.title AS title, COALESCE( NULLIF(( SELECT GROUP_CONCAT(tt.type_name ORDER BY rel.is_primary DESC, rel.sort_order ASC, rel.id ASC SEPARATOR ' / ') FROM app_movie_type_rel rel INNER JOIN app_movie_type tt ON tt.id = rel.type_id WHERE rel.movie_id = m.id ), ''), t.type_name, m.legacy_type_name ) AS typeName, COALESCE(( SELECT mm.media_url FROM app_movie_media mm WHERE mm.movie_id = m.id AND mm.media_role = 'poster' ORDER BY mm.sort_order LIMIT 1 ), m.poster_urls_csv) AS posterUrl, m.click_count AS clickCount, m.total_score AS totalScore, a.created_at AS createdAt FROM app_user_movie_action a INNER JOIN app_movie m ON m.id = a.movie_id LEFT JOIN app_movie_type t ON t.id = m.movie_type_id WHERE a.legacy_userid = #{params.legacyUserId} AND a.action_type = 'favorite'
AND m.title LIKE CONCAT('%', #{params.title}, '%')
ORDER BY ${params.sortColumn} ${params.orderKeyword} LIMIT #{params.offset}, #{params.limit}

