mapper.delete:
DELETE FROM app_movie_comment
WHERE id = #{commentId}
  AND legacy_userid = #{legacyUserId}

mapper.update:
UPDATE app_movie m
SET
  m.comment_count = (
    SELECT COUNT(1)
    FROM app_movie_comment c
    WHERE c.movie_id = #{movieId}
  ),
  m.total_score = COALESCE((
    SELECT ROUND(AVG(c.rating), 2)
    FROM app_movie_comment c
    WHERE c.movie_id = #{movieId}
      AND c.rating IS NOT NULL
  ), 0)
WHERE m.id = #{movieId}

