legacy_userid = #{legacyUserId}, author_avatar_snapshot = #{avatarUrl}, author_name_snapshot = #{nickname}, content_html = #{content}, rating = #{score}, reply_html = #{reply}, is_pinned = #{istop}, updated_at = CURRENT_TIMESTAMP
